import numpy as np


def _dev(family, y, eta):
    if family == 'binomial':
        return 2 * np.sum(np.logaddexp(0, eta) - y * eta)
    mu = np.exp(eta)
    with np.errstate(divide='ignore', invalid='ignore'):
        t = np.where(y > 0, y * np.log(y / mu), 0.0)
    return 2 * np.sum(t - (y - mu))


def irls(X, y, family, offset=None, tol=1e-10, max_iter=50):
    if family not in ('binomial', 'poisson'):
        raise ValueError('unknown family: ' + str(family))
    X = np.asarray(X, dtype=float)
    y = np.asarray(y, dtype=float)
    off = np.zeros(len(y)) if offset is None else np.asarray(offset, dtype=float)
    beta = np.zeros(X.shape[1])
    if family == 'poisson':
        beta[0] = np.log(y.sum() / np.exp(off).sum())
    dev = _dev(family, y, X @ beta + off)
    for k in range(max_iter):
        eta = X @ beta + off
        if family == 'binomial':
            mu = 1 / (1 + np.exp(-eta))
            W = mu * (1 - mu)
        else:
            mu = np.exp(eta)
            W = mu
        z = eta - off + (y - mu) / W
        beta = np.linalg.solve(X.T @ (W[:, None] * X), X.T @ (W * z))
        new_dev = _dev(family, y, X @ beta + off)
        if abs(new_dev - dev) < tol:
            return beta
        dev = new_dev
    raise ValueError('IRLS did not converge')
